const xmlEscape=(value:unknown)=>String(value??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;").replace(/\u0027/g,"&apos;");
function parseReviewWorkbook(xml:string){
 const doc=new DOMParser().parseFromString(xml,"application/xml");
 if(doc.querySelector("parsererror"))throw new Error("This is not a supported Excel XML workbook. Use the .xls file exported by Vansvriksh.");
 const sheets=Array.from(doc.getElementsByTagNameNS("*","Worksheet"));
 const readSheet=(name:string)=>{
  const sheet=sheets.find(s=>s.getAttributeNS("urn:schemas-microsoft-com:office:spreadsheet","Name")===name||s.getAttribute("ss:Name")===name);
  if(!sheet)throw new Error("The workbook is missing the "+name+" sheet.");
  const rows=Array.from(sheet.getElementsByTagNameNS("*","Row")).map(row=>Array.from(row.getElementsByTagNameNS("*","Cell")).map(cell=>cell.getElementsByTagNameNS("*","Data")[0]?.textContent??""));
  const headers=rows.shift()??[];
  return rows.filter(row=>row.some(v=>v.trim())).map(row=>Object.fromEntries(headers.map((h,i)=>[h,row[i]??""])));
 };
 const people=readSheet("People"), relationships=readSheet("Relationships");
 if(!people.length)throw new Error("The People sheet has no records.");
 if(people.some(p=>!p.person_id))throw new Error("Every People row must retain its person_id. Do not remove or edit this identifier.");
 const mapped=people.map(p=>({key:p.person_id,givenName:p.given_name||p.display_name,middleName:p.middle_name||null,familyName:p.family_name||null,gender:p.gender||"unspecified",lifeStatus:p.life_status||"alive",birthDateKind:p.birth_date_kind||"unknown",birthExactDate:p.birth_exact_date||null,birthYear:p.birth_year?Number(p.birth_year):null,birthRangeStartYear:p.birth_range_start_year?Number(p.birth_range_start_year):null,birthRangeEndYear:p.birth_range_end_year?Number(p.birth_range_end_year):null,birthOriginalText:p.birth_original_text||null,birthPlace:p.birth_place||null,birthCountry:p.birth_country||null,deathDateKind:p.death_date_kind||"unknown",deathExactDate:p.death_exact_date||null,deathYear:p.death_year?Number(p.death_year):null,deathRangeStartYear:p.death_range_start_year?Number(p.death_range_start_year):null,deathRangeEndYear:p.death_range_end_year?Number(p.death_range_end_year):null,deathOriginalText:p.death_original_text||null,biography:p.biography||null}));
 const edges=relationships.map(r=>({from:r.from_person_id,to:r.to_person_id,type:r.relationship_type})).filter(r=>r.from&&r.to&&r.type);
 return {people:mapped,relationships:edges};
}
function exportFamilyExcel(familyName:string,people:Person[],relationships:Relationship[]){
 const columns=(headers:string[],rows:Array<Array<unknown>>)=>`<Table><Row>${headers.map(v=>`<Cell><Data ss:Type="String">${xmlEscape(v)}</Data></Cell>`).join("")}</Row>${rows.map(row=>`<Row>${row.map(v=>`<Cell><Data ss:Type="String">${xmlEscape(v)}</Data></Cell>`).join("")}</Row>`).join("")}</Table>`;
 const personRows=people.map(p=>[p.id,p.display_name,p.given_name,p.middle_name,p.family_name,p.gender,p.life_status,p.birth_date_kind,p.birth_exact_date,p.birth_year,p.birth_range_start_year,p.birth_range_end_year,p.birth_original_text,p.birth_place,p.birth_country,p.death_date_kind,p.death_exact_date,p.death_year,p.death_range_start_year,p.death_range_end_year,p.death_original_text,p.biography]);
 const relationshipRows=relationships.map(r=>[r.id,r.from_person_id,r.from_name,r.relationship_type,r.to_person_id,r.to_name]);
 const instructions=[["Workbook",familyName],["Purpose","Review and correct the family data before we revise the visual layout."],["People sheet","One row per person. Keep person_id unchanged; it identifies the existing record."],["Relationships sheet","One row per connection. from_person_id and to_person_id identify the two people."],["Parent relationship","For biological_parent, adoptive_parent or step_parent: from_person_id is the parent and to_person_id is the child."],["Spouse / partner / sibling","These are peer relationships. The stored from/to direction is not a parent-child direction."],["Important","This is an export for review. Editing this workbook does not update the online family. We will use your corrected workbook to plan a safe correction/import."],["Dates","Unknown or uncertain dates are represented by their precision and original text fields; do not invent dates."],["Life status","alive and deceased are the current stored values."]];
 const sheets=[{name:"Instructions",table:columns(["Topic","Details"],instructions)},{name:"People",table:columns(["person_id","display_name","given_name","middle_name","family_name","gender","life_status","birth_date_kind","birth_exact_date","birth_year","birth_range_start_year","birth_range_end_year","birth_original_text","birth_place","birth_country","death_date_kind","death_exact_date","death_year","death_range_start_year","death_range_end_year","death_original_text","biography"],personRows)},{name:"Relationships",table:columns(["relationship_id","from_person_id","from_name","relationship_type","to_person_id","to_name"],relationshipRows)}];
 const workbook=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">${sheets.map(s=>`<Worksheet ss:Name="${s.name}">${s.table}</Worksheet>`).join("")}</Workbook>`;
 const blob=new Blob([workbook],{type:"application/vnd.ms-excel;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`${familyName.replace(/[^a-z0-9]+/gi,"-").replace(/^-|-$/g,"").toLowerCase()||"family"}-data-review.xls`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}
